# Test reads and writes on the new SurrealKV instance
curl -s -X POST http://localhost:8001/sql \
  -H "Content-Type: text/plain" \
  -H "Accept: application/json" \
  -H "surreal-ns: cohezion" \
  -H "surreal-db: main" \
  --user REDACTED \
  -d "
INFO FOR DB;
CREATE test:health_check SET status = 'ok', timestamp = time::now();
SELECT * FROM test:health_check;
DELETE test:health_check;
" 2>&1 | python3 -c "
import sys, json
data = json.load(sys.stdin)
for i, r in enumerate(data):
    status = r.get('status', 'UNKNOWN')
    if status == 'OK':
        result = r.get('result')
        if isinstance(result, dict) and 'tables' in result:
            print(f'Query {i+1}: OK — DB Info ({len(result[\"tables\"])} tables)')
        elif isinstance(result, list) and len(result) > 0:
            print(f'Query {i+1}: OK — {json.dumps(result[0], default=str)[:100]}')
        else:
            print(f'Query {i+1}: OK — {str(result)[:100]}')
    else:
        print(f'Query {i+1}: {status} — {r.get(\"result\", \"\")[:100]}')
"

