# Test VERSION clause with versioning enabled
curl -s -X POST http://localhost:8001/sql \
  -H "Content-Type: text/plain" \
  -H "Accept: application/json" \
  -H "surreal-ns: cohezion" \
  -H "surreal-db: vault" \
  --user REDACTED \
  -d "
CREATE neurons:version_test SET 
  title = 'Version Test v1',
  path = 'test/version',
  tags = ['test'],
  valid_from = d'2026-04-10T00:00:00Z',
  activation = 0.5,
  stage = 'active';

SELECT title, stage FROM neurons:version_test;

SELECT title, stage FROM neurons:version_test VERSION d'2026-04-11T04:00:00Z';

UPDATE neurons:version_test SET title = 'Version Test v2', stage = 'updated';

SELECT title, stage FROM neurons:version_test;

SELECT title, stage FROM neurons:version_test VERSION d'2026-04-11T04:01:00Z';

DELETE neurons:version_test;
" 2>&1 | python3 -c "
import sys, json
labels = ['CREATE', 'SELECT current', 'SELECT VERSION (before update)', 'UPDATE', 'SELECT after update', 'SELECT VERSION (after update)', 'DELETE']
data = json.load(sys.stdin)
for i, d in enumerate(data):
    label = labels[i] if i < len(labels) else f'Query {i+1}'
    if d['status'] == 'OK':
        result = d.get('result')
        if isinstance(result, list) and len(result) > 0:
            print(f'{label}: OK — {json.dumps(result[0], default=str)[:120]}')
        else:
            print(f'{label}: OK — {str(result)[:80]}')
    else:
        print(f'{label}: {d[\"status\"]} — {d.get(\"result\", \"\")[:120]}')
"

