    """
    if cls._profiles_cache is not None:
        return cls._profiles_cache

    import yaml
    from pathlib import Path

    config_path = Path(__file__).parents[2] / "config" / "model_profiles.yaml"
    if not config_path.exists():
        # Also check from CWD
        config_path = Path("config/model_profiles.yaml")

    profiles: dict = {}
    if config_path.exists():
        try:
            with open(config_path) as f:
                raw = yaml.safe_load(f)
            # Merge all tier sections into flat model dict
            for section_key in ("lemonade_hybrid", "lemonade_cpu", "lemonade_gpu",
                                "lemonade_embeddings", "lemonade_multimodal", "ollama_cloud"):
